const escape=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function streetReviewHTML(streets,card){if(!streets)return '';return `<section class="street-review"><h3>Round-by-round · suggested approach</h3><p class="review-note">Based on what you could know then. These are high-level alternatives, not solver-certified optimal actions.</p><div class="street-grid">${streets.map(s=>`<section class="street-card"><h4>${escape(s.street)}</h4>${s.board.length?`<div class="cards street-board">${s.board.map(card).join('')}</div>`:''}<p class="street-focus">${escape(s.focus)}</p>${s.texture?`<p class="review-note">${escape(s.texture)}</p>`:''}${s.decisions.length?s.decisions.map(d=>`<div class="street-decision"><strong>You: ${escape(d.action)} <span>· ${escape(d.position)}</span></strong><p>${escape(d.context)}</p><p class="street-guidance"><b>Consider</b> ${escape(d.guidance)}</p></div>`).join(''):`<p class="review-note">${escape(s.status)}</p>`}</section>`).join('')}</div></section>`;}
